import {
  StyleSheet,
  Text,
  TextInput,
  View,
  type TextInputProps,
} from "react-native";

type TextFieldProps = Pick<
  TextInputProps,
  | "autoCapitalize"
  | "keyboardType"
  | "textContentType"
  | "multiline"
  | "placeholder"
> & {
  label: string;
  value: string;
  onChangeText: (value: string) => void;
  errorMessage?: string;
  testID?: string;
};

/**
 * The app's one labelled text input: a 44pt minimum height and a visible
 * error state driven by a boolean style prop.
 */
export function TextField({
  label,
  value,
  onChangeText,
  errorMessage,
  testID,
  ...inputProps
}: TextFieldProps) {
  const hasError = Boolean(errorMessage);

  return (
    <View style={styles.container}>
      <Text style={styles.label}>{label}</Text>
      <TextInput
        {...inputProps}
        value={value}
        onChangeText={onChangeText}
        style={[styles.input, hasError && styles.inputError]}
        testID={testID}
        accessibilityLabel={label}
      />
      {hasError ? (
        <Text
          style={styles.error}
          testID={testID ? `${testID}-error` : undefined}
        >
          {errorMessage}
        </Text>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    gap: 4,
  },
  label: {
    fontSize: 14,
    lineHeight: 20,
    fontWeight: "600",
    color: "#1b1f24",
  },
  input: {
    fontSize: 16,
    lineHeight: 24,
    fontWeight: "400",
    color: "#1b1f24",
    minHeight: 44,
    borderWidth: 2,
    borderRadius: 8,
    borderColor: "#767e8a",
    paddingHorizontal: 12,
  },
  inputError: {
    borderColor: "#b3271e",
  },
  error: {
    fontSize: 13,
    lineHeight: 18,
    fontWeight: "400",
    color: "#b3271e",
  },
});

